function imageAttributes(file,sizes='(max-width:700px) 90vw, 60vw') {
 const data=imageMetadata[file.split('?')[0]];
 if(!data)return '';
 const sources=[...data.variants,[file,data.width]].map(([src,width])=>A+src+' '+width+'w').join(', ');
 return ' width="'+data.width+'" height="'+data.height+'"'+(data.variants.length?' srcset="'+sources+'" sizes="'+sizes+'"':'');
}
function mediaImage(file,alt,eager=false,sizes) {return '<img src="'+A+file+'"'+imageAttributes(file,sizes)+' alt="'+alt+'" loading="'+(eager?'eager':'lazy')+'" decoding="async">'}
function setImageSource(img,file){const data=imageMetadata[file.split('?')[0]];img.removeAttribute('srcset');img.removeAttribute('sizes');if(data){img.width=data.width;img.height=data.height;if(data.variants.length){img.srcset=[...data.variants,[file,data.width]].map(([src,width])=>A+src+' '+width+'w').join(', ');img.sizes='(max-width:700px) 90vw, 55vw';}}img.src=A+file;}
function image(file,alt,caption='',eager=false){return '<button class="image-button" data-image="'+file+'" data-caption="'+caption+'" aria-label="Amplia: '+alt+'">'+mediaImage(file,alt,eager)+'</button>'}
function heroLetters(text,extra=''){return '<span class="hero-line '+extra+'" aria-hidden="true">'+[...text].map(letter=>'<span class="hero-letter">'+letter+'</span>').join('')+(text==='MARC'?'<sup class="hero-mark">↗</sup>':'')+'</span>'}
function figure(file,alt,label,n=''){return `<figure>${image(file,alt,label)}<figcaption class="image-caption"><span>${label}</span><span>${n}</span></figcaption></figure>`}
function card(p){const data=imageMetadata[p.cover];return `<a class="project-card card-${p.className} reveal" style="--index-ratio:${data.width}/${data.height}" href="#/${p.experiment?'experimentacio':'project'}/${p.id}" aria-label="Veure ${p.title}${p.subtitle?' · '+p.subtitle:''}"><div class="media">${mediaImage(p.cover,p.alt,false,p.id==='the-shadow-set'?'100vw':'(max-width:600px) 100vw, 65vw')}<div class="card-overlay"><div class="card-label"><h2>${p.display}</h2>${p.subtitle?`<p class="card-subtitle">${p.subtitle}</p>`:''}</div></div></div></a>`}
function projectRow(items){return `<div class="project-row${items.length===1&&items[0].id==='mirall-fusta'?' project-row-mirall':''}" style="--row-columns:${items.map(p=>{const d=imageMetadata[p.cover];return (d.width/d.height).toFixed(8)+'fr';}).join(' ')}">${items.map(card).join('')}</div>`}
function featuredHome(){const p=projects.find(p=>p.id==='ev-charger');return `<section class="ev-feature" aria-label="Amazon Dock, projecte protagonista" data-motion="off"><a class="ev-hit" href="#/project/ev-charger" aria-label="Veure el projecte Amazon Dock"><div class="ev-visual">${mediaImage(p.cover,p.alt,false,'(max-width:600px) 155vw, 80vw')}</div><div class="ev-title"><h2>Amazon<br>Dock</h2><span class="ev-arrow" aria-hidden="true">↗</span></div></a><button class="ev-motion" type="button" aria-label="Activa el moviment d’Amazon Dock" aria-pressed="false"><svg class="ev-play" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 2l10 6-10 6z"/></svg><svg class="ev-pause" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 2h3v12H4zm5 0h3v12H9z"/></svg></button></section>`}
function coverHome(){const m=window.coverMedia;const src=m.directory+'frame-001.webp';return `<section class="cover-scene" aria-label="Presentació de Marc Moncunill" style="--cover-ratio:${m.width/m.height};--front-cut:${100-m.foregroundEnd}%"><div class="cover-stage"><div class="cover-art"><img src="${src}" width="${m.width}" height="${m.height}" alt="Aixeta de cuina A3 de Marc Moncunill, vista a 45 graus, amb capçal extraïble i mànega d’acer trenat" fetchpriority="high" decoding="async"></div><h1 class="cover-name" aria-label="Marc Moncunill"><span class="cover-first" aria-hidden="true">MARC</span><span class="cover-last" aria-hidden="true">MONCUNILL</span></h1><div class="cover-art cover-art-front" aria-hidden="true"><img src="${src}" width="${m.width}" height="${m.height}" alt="" decoding="async"></div><button class="cover-control" type="button" aria-label="Activa l’animació amb scroll" aria-pressed="false"><svg class="control-pause" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 2h3v12H4zm5 0h3v12H9z"/></svg><svg class="control-play" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 2l10 6-10 6z"/></svg></button></div></section>`}
function home(){return `${coverHome()}
 <section class="work" id="work" aria-label="Tots els projectes"><div class="section-line"><span>Tots els projectes</span><span>01 — 06</span></div>${featuredHome()}<div class="project-grid">${projectRow(homeProjects.filter(p=>['a3-collection','safata-i-bol'].includes(p.id)))}${projectRow(homeProjects.filter(p=>['ampolla-oli','the-shadow-set'].includes(p.id)))}${projectRow(homeProjects.filter(p=>p.id==='mirall-fusta'))}</div></section>
 <section class="experimentation" id="experimentacio" aria-label="Experimentació"><div class="section-line"><h2>EXPERIMENTACIÓ</h2><span>Materials · Resina</span></div><div class="experiment-grid"><a class="project-card materials-card reveal" style="--index-ratio:2200/2933" href="#/experimentacio/nous-materials" aria-label="Veure ${publicationTitle}"><div class="media">${mediaImage('materials/portada.webp','Mostres de materials translúcids blaus i transparents, amb peces de serradura i recipients',false,'(max-width:600px) 100vw, 35vw')}<div class="card-overlay"><h2>${publicationTitle}</h2></div></div></a>${card(projects.find(p=>p.experiment))}</div></section>
 <section class="about" id="about"><div class="eyebrow">Sobre mi</div><div><h2>Marc Moncunill</h2><p>Estudio disseny de producte a ESDAPC. Aquí hi trobaràs projectes de griferia, envasos, jocs i objectes de fusta, amb els seus esbossos, renders i prototips.</p><p>Treballo amb modelatge 3D i fabricació al taller, sobretot amb fusta i resina.</p><div class="contact-block" id="contacte"><h3 class="eyebrow">Contacte</h3><div class="contact-links"><a href="mailto:marcmoncunill@gmail.com">marcmoncunill@gmail.com ↗</a><a href="https://www.instagram.com/marcmoncunill/" target="_blank" rel="noopener">Instagram · @marcmoncunill ↗</a></div><div class="contact-location">Igualada / Barcelona</div></div></div></section>`}
function facts(items){const ordered=[...items.filter(([label])=>label==='Autoria'),...items.filter(([label])=>label!=='Autoria')];return `<aside class="project-credits" aria-label="Crèdits del projecte">${ordered.map(([label,value])=>`<p class="project-credit${label==='Autoria'?' credit-author':''}"><span class="project-credit-label">${label}: </span>${value}</p>`).join('')}</aside>`}
function intro(p,index){return `<div class="project-intro"><div class="project-breadcrumb"><a href="#/#${p.experiment?'experimentacio':'work'}">← ${p.experiment?'Experimentació':'Tots els projectes'}</a><span>${p.sectionLabel||(p.experiment?'Taller · Resina':String(index+1).padStart(2,'0')+' / 06')}</span></div><div class="project-title-row"><div><div class="eyebrow">${p.category} / ${p.year}</div><h1>${p.id==='a3-collection'?'A<sup>3</sup><br>Collection':p.display}</h1>${p.subtitle?`<p class="project-subtitle">${p.subtitle}</p>`:''}</div><p class="project-deck">${p.deck}</p></div></div>`}
function opening(p,index,caption=''){const side=p.openingSide||(index%2?'left':'right');return `<section class="project-opening opening-image-${side}" aria-label="Presentació de ${p.title||p.display}">${intro(p,index)}<div class="project-hero${p.id==='nous-materials'?' materials-hero':''}">${p.openingVideo?mirrorMotion(p):p.openingTexture?`<div class="opening-texture" aria-hidden="true"><img src="${A+(p.openingCover||p.cover)}" alt="" loading="eager" decoding="async"></div>`:image(p.openingCover||p.cover,p.openingAlt||p.alt,caption||(p.experiment?'Conjunt de peces del taller':p.display),true)}${p.coverCredit?`<p class="opening-credit">${p.coverCredit}</p>`:''}</div></section>`}
function evDetailOpening(p,index,content=opening(p,index)){return `<section class="ev-detail-scene" data-motion="on" aria-labelledby="ev-detail-title"><div class="ev-detail-stage"><img class="ev-detail-poster" src="assets/ev-charger-v05-referencia/poster-v05.webp" width="3840" height="2160" alt="Amazon Dock, estació de càrrega EV: render frontal corregit" fetchpriority="high" decoding="async"><canvas class="ev-detail-canvas" role="img" aria-label="Amazon Dock: seqüència del frontal, interior, mànec, reixeta i revers"></canvas><h2 class="ev-detail-title" id="ev-detail-title">Amazon Dock</h2><p class="ev-detail-status" role="status"></p></div></section>${content}`}
function next(p){return '<a class="next-project" href="#/project/'+p.id+'"><div><div class="eyebrow">Següent projecte</div><h2>'+p.display+'</h2>'+(p.subtitle?'<p class="next-subtitle">'+p.subtitle+'</p>':'')+'<span class="next-arrow" aria-hidden="true">↗</span></div>'+mediaImage(p.cover,p.alt,false,'(max-width:700px) 90vw, 50vw')+'</a>'}
