function resinProject(p,index){return `<article class="project project-joc resin-case">
 ${opening(p,index,'Composició conjunta de peces de Marc Moncunill i companys de classe')}
 <section class="project-summary">${facts([['Context','Maquetes i Prototips II<br>2n de Disseny de producte · ESDAPC'],['Curs','2024–25'],['Autoria','Marc Moncunill · dues peces'],['Treball','Models d’escuma, motlles de silicona i reproducció en resina']])}<div><h2>Aprendre a reproduir una forma</h2><p>L’exercici consistia a fabricar dues peces a partir d’elements arquitectònics i reproduir-les en resina. El treball era fer el recorregut complet al taller: construir els originals, preparar el motlle i obtenir les còpies.</p><p>Vaig partir d’una de les torres amb cúpula de l’Hotel Miramar Resort de Michael Graves i d’un volum cònic del Museu Exploratorium de Bernard Tschumi. Aquestes referències es van simplificar en dos models d’escuma de poliuretà d’alta densitat.</p></div></section>
 <section class="project-section resin-workshop" aria-labelledby="resin-workshop-title"><div class="section-heading"><div class="eyebrow">01 / Al taller</div><h2 id="resin-workshop-title">Materials i eines</h2></div><div class="resin-workshop-grid"><div><h3>Models</h3><p>Escuma de poliuretà d’alta densitat, massilla acrílica, vareta de PVC, plastilina i cianoacrilat.</p><p>Serra de cinta, llimes, paper de vidre i esponges abrasives, polidora de disc i trepant de columna.</p></div><div><h3>Motlles</h3><p>Silicona bicomponent RTV-1607 i catalitzador. Base, cartró ploma i cola termofusible per construir el recipient.</p><p>Espàtula, regla, llapis i pistola de cola termofusible.</p></div><div><h3>Còpies</h3><p>Resina rígida de poliuretà bicomponent i colorants compatibles.</p><p>Balança, vasos i llistó per barrejar. Cúter i llimes per al repàs final.</p></div></div></section>
 <section class="project-section resin-process" aria-labelledby="resin-process-title"><div class="section-heading"><div class="eyebrow">02 / Procés</div><div><h2 id="resin-process-title">Del model a la còpia</h2><p>Primer, construir i acabar les formes a mà. Després, fer el negatiu de silicona i comprovar com es reprodueixen en resina.</p></div></div><div class="resin-process-grid">${resinSteps.map((s,i)=>`<figure>${image(s.file,s.alt,s.title)}<figcaption><div class="resin-step-title"><span>${String(i+1).padStart(2,'0')}</span><h3>${s.title}</h3></div><p>${s.copy}</p></figcaption></figure>`).join('')}</div></section>
 <section class="project-section resin-result" aria-labelledby="resin-result-title"><div class="section-heading"><div class="eyebrow">03 / Resultat</div><div><h2 id="resin-result-title">Les dues peces</h2><p>Aquestes són les dues peces que vaig desenvolupar: la cilíndrica amb cúpula, en rosa, i el cos amb el volum cònic, en blau. La composició de la portada combina aquestes peces amb les dels companys de classe.</p></div></div>${figure('joc-colour.webp','Les dues peces pròpies de Marc: cos cònic blau i peça cilíndrica rosa amb cúpula','Peces de Marc Moncunill · Resina de poliuretà','')}</section>
 <p class="project-note">Maquetes i Prototips II · ESDAPC · 2024–25. Fotografies de la memòria del treball i composicions de taller realitzades amb companys de classe.</p><a class="publication-back" href="#/#experimentacio">← Tornar a experimentació</a></article>`}
function projectDetail(p,index){if(p.id==='ev-charger')return window.amazonDockProject(p,index);if(p.id==='joc-infantil')return resinProject(p,index);if(p.id==='the-shadow-set')return shadowProject(p,index);if(p.id==='mirall-fusta')return mirrorProject(p,index);if(p.id==='safata-i-bol')return safataProject(p,index);if(p.id==='ampolla-oli')return oilProject(p,index);const d=detail[p.id];return `<article class="project project-${p.className}">${p.id==='ev-charger'?evDetailOpening(p,index):opening(p,index)}<section class="project-summary">${facts([[p.experiment?'Exercici':'Projecte',p.display],['Any',p.year],['Autoria','Marc Moncunill'],...d.facts])}<div><h2>${d.heading}</h2><p>${d.copy}</p></div></section><section class="project-section"><div class="section-heading"><div class="eyebrow">01 / Imatges</div><h2>Detalls i procés</h2></div><div class="pair">${d.images.map(([file,alt,label],i)=>figure(file,alt,label,String(i+1).padStart(2,'0'))).join('')}</div></section><p class="project-note">${d.note}</p>${p.experiment?'<a class="publication-back" href="#/#experimentacio">← Tornar a experimentació</a>':next(productProjects[(index+1)%productProjects.length])}</article>`}
function oilProject(p,index){return `<article class="project project-ampolla oil-case">
 ${opening(p,index,'Contrapposto · Visualització en un restaurant')}
 <section class="project-summary">${facts([['Context','Projectes II · 2n Producte<br>ESDAPC · 2024–25'],['Autoria','Marc Moncunill'],['Materials proposats','Vidre verd fosc<br>Tap de rosca d’alumini'],['Eines','Rhinoceros · KeyShot<br>Impressió 3D']])}<div><h2>Un envàs per a oli d’oliva</h2><p>El projecte parteix del repte del Vidrala Masterglass Design Contest: dissenyar un envàs de vidre. La proposta és una ampolla per a oli d’oliva verge extra català, pensada per a la taula i la restauració.</p><p>La forma evoluciona d’un cos orgànic a una silueta asimètrica, marcada per una aresta que recorre un dels costats. Es proposa vidre verd fosc per protegir l’oli de la llum, un tap de rosca d’alumini i l’etiqueta a la part posterior.</p></div></section>
 <section class="project-section oil-dimensions" aria-labelledby="oil-dimensions-title"><div class="section-heading"><div class="eyebrow">01 / Mides</div><h2 id="oil-dimensions-title">Forma i dimensions</h2></div><div class="oil-dimensions-grid"><div class="oil-plan-panel"><dl class="oil-measurements"><div><dt>Alçada total</dt><dd>195 <span>mm</span></dd></div><div><dt>Fons · Vista superior</dt><dd>78,4 <span>mm</span></dd></div><div><dt>Amplada de la base</dt><dd>49,41 <span>mm</span></dd></div><div><dt>Amplada del coll</dt><dd>20 <span>mm</span></dd></div></dl>${figure('contrapposto/planol-mides-v19.webp','Plànol original amb alçat, perfil i vista superior. Cotes: alçada 195 mm, base 49,41 mm, fons 78,4 mm, coll 20 mm i vèrtex lateral a 67,2 mm','Plànol original · Cotes en mm')}</div><div class="oil-table-panel">${figure('contrapposto/taula-v19.webp','Render de l’ampolla Contrapposto en una taula amb plats de menjar, gots i flors','Contrapposto a taula · Visualització digital')}</div></div></section>
 <section class="project-section oil-prototype" aria-labelledby="oil-prototype-title"><div class="section-heading"><div class="eyebrow">02 / Prototip</div><div><h2 id="oil-prototype-title">Del model 3D a la maqueta</h2><p>La maqueta impresa en 3D permet observar el volum des de diferents angles i comparar el perfil, l’aresta lateral i la forma del coll.</p></div></div>${figure('contrapposto/prototip-v19.webp','Tres vistes del prototip físic imprès en 3D, de color clar, amb les línies i les unions de la impressió visibles','Tres vistes del prototip · Fotografies amb correcció de llum')}</section>
 <p class="project-note">Projecte acadèmic · Projectes II · 2024–25. Les imatges del producte en vidre són visualitzacions digitals. Les fotografies finals mostren la maqueta física impresa en 3D.</p>${next(productProjects[(index+1)%productProjects.length])}</article>`}
