function safataProject(p,index){return `<article class="project project-safata safata-case">
 ${opening(p,index,'Safata i bol · Conjunt')}
 <section class="project-summary">${facts([['Context','Tall de fusta · 3r Producte<br>ESDAPC · 2025–26'],['Autoria','Marc Moncunill'],['Materials','Avet de 18 mm i til·ler<br>Plantilla de DM · Vernís mate'],['Treball','Disseny, fresat, talla i acabats']])}<div><h2>Una safata i un bol fets al taller</h2><p>La safata parteix d’un tauler allistonat d’avet de 18 mm. Els buits es fresen amb una plantilla de DM i les nanses es retallen amb trepant i caladora. El contorn es treballa amb serra de cinta, llimes i paper de vidre.</p><p>El bol es talla a partir d’un bloc de til·ler. Les gúbies permeten buidar-ne l’interior i arrodonir-ne l’exterior abans del polit. Les dues peces s’acaben amb vernís transparent mate.</p><div class="project-document-actions"><a class="pdf-button" href="${A}documents/safata-i-bol-marc-moncunill.pdf" target="_blank" rel="noopener" aria-label="Obrir el treball de Safata i bol en PDF, en una pestanya nova">Obrir el treball (PDF) ↗</a></div></div></section>
 <section class="project-section safata-result" aria-labelledby="safata-result-title"><div class="section-heading"><div class="eyebrow">01 / Resultat</div><h2 id="safata-result-title">Les dues peces</h2></div><div class="safata-media-grid">${figure('safata/resultat-safata.webp','Safata d’avet acabada, amb buits fresats i dues nanses','Safata · Avet','01')}${figure('safata/resultat-bol.webp','Bol de til·ler acabat i envernissat, fotografiat de costat','Bol · Til·ler','02')}</div></section>
 <section class="project-section safata-process" aria-labelledby="safata-process-title"><div class="section-heading"><div class="eyebrow">02 / Procés</div><div><h2 id="safata-process-title">Etapes al taller</h2><p>La plantilla i el fresat de la safata, la talla del bol i els acabats de les dues peces.</p></div></div><div class="resin-process-grid safata-process-grid">${safataSteps.map((s,i)=>`<figure>${image(s.file,s.alt,s.title)}<figcaption><div class="resin-step-title"><span>${String(i+1).padStart(2,'0')}</span><h3>${s.title}</h3></div><p>${s.copy}</p></figcaption></figure>`).join('')}</div></section>
 <p class="project-note">Projecte acadèmic · Tall de fusta · 3r de Disseny de producte · 2025–26. Fotografies de les peces i del procés extretes de la memòria del treball.</p>${next(productProjects[(index+1)%productProjects.length])}</article>`}
let mirrorMotionCleanup=null;
function mirrorMotion(p){return '<div class="mirror-motion"><video id="mirror-reflection" autoplay muted loop playsinline preload="auto" disablepictureinpicture disableremoteplayback poster="'+A+p.openingPoster+'" aria-label="Mirall de fusta amb núvols en moviment al reflex"><source src="'+A+p.openingVideo+'" type="video/mp4">El navegador no pot reproduir aquest vídeo.</video><button class="motion-toggle" type="button" aria-controls="mirror-reflection" aria-pressed="false">Pausa el reflex <span aria-hidden="true">Ⅱ</span></button></div>'}
function setupMirrorMotion(){
 const video=document.querySelector('#mirror-reflection');if(!video)return;
 const toggle=document.querySelector('.motion-toggle');let userPaused=false;
 document.querySelector('.mirror-immersive .project-intro')?.append(toggle);
 video.muted=true;video.defaultMuted=true;video.autoplay=true;video.loop=true;
 const label=()=>{const playing=!video.paused;toggle.setAttribute('aria-pressed',String(playing));toggle.innerHTML=playing?'Pausa el reflex <span aria-hidden="true">Ⅱ</span>':'Reprodueix el reflex <span aria-hidden="true">▶</span>';};
 const play=()=>{if(!userPaused){const pending=video.play();pending?.catch(label);}};
 const resume=()=>{if(!document.hidden&&!userPaused)play();};
 const pause=()=>{label();resume();};
 const click=()=>{userPaused=!video.paused;if(userPaused)video.pause();else play();label();};
 video.addEventListener('canplay',play);video.addEventListener('play',label);video.addEventListener('pause',pause);toggle.addEventListener('click',click);document.addEventListener('visibilitychange',resume);document.addEventListener('pointerdown',resume);window.addEventListener('pageshow',resume);play();label();
 mirrorMotionCleanup=()=>{video.removeEventListener('canplay',play);video.removeEventListener('play',label);video.removeEventListener('pause',pause);toggle.removeEventListener('click',click);document.removeEventListener('visibilitychange',resume);document.removeEventListener('pointerdown',resume);window.removeEventListener('pageshow',resume);video.pause();};
}
