function shadowOpening(p,index){const base='components/shadow-set-v05/';return `<section class="shadow-hero" data-entry-state="loading" aria-busy="true" aria-labelledby="shadow-title">
 <picture class="shadow-static" aria-hidden="true"><source media="(max-width:700px)" srcset="assets/shadow-entry-mobile.png"><source media="(max-width:1000px)" srcset="assets/shadow-entry-tablet.png"><img class="shadow-fallback" src="assets/shadow-entry-desktop.png" fetchpriority="high" decoding="sync" alt="Peces modulars translúcides blaves i taronges de The Shadow Set, també per darrere del títol."></picture>
 <div class="shadow-stage" tabindex="0" role="application" aria-label="Peces de metacrilat interactives" aria-describedby="shadow-scene-instructions"></div>
 <div class="shadow-copy"><div class="shadow-entry-back"><a href="#/#work">← Tots els projectes</a><span>${String(index+1).padStart(2,'0')} / 06</span></div><p class="project-category">${p.category} / ${p.year}</p><h1 id="shadow-title">${p.display}</h1><p class="project-description">${p.deck}</p></div>
 <p id="shadow-scene-instructions" class="visually-hidden">Passa el ratolí entre les peces per empènyer-les. Amb la zona de joc enfocada, les fletxes mouen el cursor virtual, l'espai pausa el moviment i R reinicia la composició. En pantalla tàctil, toca una peça o mou-hi el dit sense impedir el desplaçament de la pàgina.</p>
 <div class="shadow-controls" aria-label="Controls de les peces" hidden><button type="button" data-shadow-pause aria-pressed="false">Pausa</button><button type="button" data-shadow-reset>Reinicia</button></div><p class="shadow-status visually-hidden" role="status" aria-live="polite"></p>
 </section>`}
function shadowProject(p,index){return `<article class="project project-shadow shadow-case">
 ${shadowOpening(p,index)}
 <section class="project-summary">${facts([['Context','Enemic invisible · Projectes III<br>ESDAPC · 2025–26'],['Autoria','Marc Moncunill'],['Sistema','8 formes diferents · 26 peces'],['Material','Metacrilat fluorescent blau i taronja<br>3 mm · Tall làser']])}<div><h2>Enemic invisible</h2><p>L’encàrrec era un intercanvi entre companys: cadascú dissenyava un sistema i n’entregava els arxius i les instruccions perquè un altre el fabriqués i el posés a prova sense explicacions directes.</p><p>The Shadow Set és un conjunt de peces planes que s’uneixen per ranures. Es poden girar, repetir i combinar per construir volums diferents. La llum travessa el metacrilat blau i taronja i projecta colors que se superposen: la composició canvia tant amb el muntatge com amb la llum.</p></div></section>
 <section class="project-section shadow-compositions" aria-label="Composicions de The Shadow Set"><div class="shadow-composition-grid">${figure('shadow/composicio-01.webp','Primera composició tridimensional amb les peces de metacrilat blau i taronja','Composició 01 · Visualització digital','01')}${figure('shadow/composicio-02.webp','Segona composició tridimensional amb les mateixes peces de metacrilat','Composició 02 · Visualització digital','02')}</div></section>
 <section class="shadow-instructions" aria-labelledby="shadow-instructions-title"><div class="shadow-instructions-copy"><div class="eyebrow">01 / Instruccions</div><h2 id="shadow-instructions-title">Fabricar, muntar i provar</h2><p>El document acompanya els arxius de tall i explica com produir les peces i començar a utilitzar el sistema. Era la informació que havia de rebre l’altra persona per poder treballar-hi de manera autònoma.</p><ol class="shadow-use-steps"><li><h3>Tallar</h3><p>El disseny preveu dues planxes A4 de metacrilat fluorescent de 3 mm, una de blava i una de taronja, tallades amb làser.</p></li><li><h3>Encaixar</h3><p>Les ranures connecten les peces planes per formar estructures tridimensionals. La composició es pot desmuntar i tornar a combinar.</p></li><li><h3>Posar-hi llum</h3><p>Una làmpada o la llum del sol permeten observar les projeccions de color. Canviant l’angle de la llum o la posició de les peces, també canvia el que es projecta.</p></li></ol></div>
 <aside class="shadow-reader" aria-label="Lector de les instruccions de The Shadow Set"><div class="shadow-reader-controls"><label for="shadow-page">Pàgina <select id="shadow-page">${Array.from({length:shadowPageCount},(_,i)=>`<option value="${i+1}">${String(i+1).padStart(2,'0')}</option>`).join('')}</select> de ${shadowPageCount}</label></div><div class="shadow-reader-stage"><button class="shadow-reader-nav" data-shadow-step="-1" type="button" aria-label="Pàgina anterior de les instruccions" disabled>←</button><figure class="shadow-reader-sheet">${image(shadowPageAsset(1),'Portada del PDF d’instruccions de The Shadow Set','The Shadow Set · Instruccions · Pàgina 1 de 4',true)}<figcaption class="image-caption"><span id="shadow-page-status" aria-live="polite">Pàgina 1 de 4</span><span>Amplia ↗</span></figcaption></figure><button class="shadow-reader-nav" data-shadow-step="1" type="button" aria-label="Pàgina següent de les instruccions">→</button></div><div class="shadow-reader-download"><a class="pdf-button" href="${shadowPDF}" target="_blank" rel="noopener">Obrir el PDF ↗</a><a class="pdf-button pdf-button-secondary" href="${shadowPDF}" download="Marc-Moncunill-The-Shadow-Set-Instruccions.pdf">Descarregar ↓</a><p>Edició web · Dades personals i bancàries del pressupost ocultes.</p></div></aside></section>
 <section class="project-section shadow-result" aria-labelledby="shadow-result-title"><div class="section-heading"><div class="eyebrow">02 / Resultat</div><div><h2 id="shadow-result-title">La composició amb llum solar</h2><p>La proposta no acaba en el volum construït. La llum travessa el metacrilat blau i taronja i projecta els colors sobre la superfície. Quan les projeccions se superposen, apareixen altres tons i formes.</p></div></div>${figure('shadow/llum-solar.webp','Visualització d’una composició de The Shadow Set al costat d’una finestra, amb projeccions de color blau i taronja','Visualització de la interacció del metacrilat amb la llum solar','')}</section><p class="project-note">Projecte acadèmic · Enemic invisible · Projectes III · 2025–26. Disseny del sistema i de les instruccions: Marc Moncunill.</p>${next(productProjects[(index+1)%productProjects.length])}</article>`}
function showShadowPage(n){shadowPage=Math.max(1,Math.min(shadowPageCount,Number(n)||1));const reader=document.querySelector('.shadow-reader');if(!reader)return;const button=reader.querySelector('[data-image]');const file=shadowPageAsset(shadowPage);button.dataset.image=file;button.dataset.caption=`The Shadow Set · Instruccions · Pàgina ${shadowPage} de ${shadowPageCount}`;button.setAttribute('aria-label',`Amplia la pàgina ${shadowPage} de les instruccions`);const img=button.querySelector('img');setImageSource(img,file);img.alt=`The Shadow Set · Instruccions · Pàgina ${shadowPage} de ${shadowPageCount}`;reader.querySelector('select').value=String(shadowPage);reader.querySelector('#shadow-page-status').textContent=`Pàgina ${shadowPage} de ${shadowPageCount}`;reader.querySelector('[data-shadow-step="-1"]').disabled=shadowPage===1;reader.querySelector('[data-shadow-step="1"]').disabled=shadowPage===shadowPageCount;}
document.addEventListener('click',event=>{const step=event.target.closest('[data-shadow-step]');if(step)showShadowPage(shadowPage+Number(step.dataset.shadowStep));});
document.addEventListener('change',event=>{if(event.target.id==='shadow-page')showShadowPage(event.target.value);});
const publicationTitle='Experimentació amb nous materials';
const publicationPageCount=57;
const publicationSections=[['Agar agar',5],['Espuma',13],['Tapioca',17],['Maicena',21],['Serradura',25],['Morter',29],['Guix',35],["Closca d’ou",39],['Glicerina',45],['Fosa de plàstic',47]];
const publicationPDF=A+'materials/taller-nous-materials-marc-moncunill.pdf?v=6';
function publicationAsset(page){return `materials/pagina-${String(page).padStart(2,'0')}.webp?v=6`}
let publicationPage=1;
function publication(){return `<article class="project publication">
 ${opening({id:'nous-materials',display:publicationTitle,experiment:true,sectionLabel:'Publicació',category:'Experimentació · Publicació',year:'2025–26',openingSide:'left',cover:'materials/tamboret-morter.webp',alt:'Fotografia del tamboret de morter amb superfície plegada i potes de fusta',deck:'Proves de materials, mostres i processos recollits en una publicació.'},-1,'Experimentació amb morter · Tamboret')}
 <section class="project-summary">${facts([['Format',`Publicació · ${publicationPageCount} pàgines`],['Autoria','Marc Moncunill Noguera'],['Context','Taller Experimental de Nous Materials<br>ESDAPC · Disseny de producte'],['Curs','2025–26']])}<div><h2>Un recull de les proves del taller</h2><p>Aquesta publicació documenta l’experimentació amb diferents barreges, textures i formes. Recull receptes, fotografies de les mostres i alguns moments del procés.</p><p>No parteix d’un únic producte: reuneix els assaigs del taller, des de barreges amb agar-agar, tapioca o serradura fins a proves amb morter i peces translúcides.</p><a class="pdf-button pdf-button-secondary" href="#/experimentacio/nous-materials/lectura">Llegir la publicació ↓</a></div></section>
 <section class="publication-reader" id="lectura" aria-label="Lector de la publicació"><div class="section-heading"><div class="eyebrow">Índex de materials</div><h2>${publicationTitle}</h2></div>
 <div class="publication-shortcuts" aria-label="Índex de materials">${publicationSections.map(([title,page],i)=>`<button type="button" data-publication-page="${page}"><span class="publication-chapter">${String(i+1).padStart(2,'0')} / ${title}</span><span>P. ${String(page).padStart(2,'0')}</span></button>`).join('')}</div>
 <div class="publication-controls"><label for="publication-page">Pàgina <select id="publication-page">${Array.from({length:publicationPageCount},(_,i)=>`<option value="${i+1}">${String(i+1).padStart(2,'0')}</option>`).join('')}</select> de ${publicationPageCount}</label></div>
 <div class="publication-stage"><button class="publication-nav publication-prev" type="button" data-publication-step="-1" aria-label="Pàgina anterior" disabled>←</button><figure class="publication-sheet">${image(publicationAsset(1),'Pàgina 1 de la publicació: portada',`Publicació · Pàgina 1 de ${publicationPageCount}`,true)}<figcaption class="image-caption"><span id="publication-status" aria-live="polite">Pàgina 1 de ${publicationPageCount}</span><span>Amplia la pàgina ↗</span></figcaption></figure><button class="publication-nav publication-next" type="button" data-publication-step="1" aria-label="Pàgina següent">→</button></div>
 <div class="publication-download"><p>Consulta totes les pàgines aquí o obre el document en PDF.</p><a class="pdf-button" href="${publicationPDF}" target="_blank" rel="noopener">Obrir el PDF complet ↗</a><a class="pdf-button pdf-button-secondary" href="${publicationPDF}" download="Marc-Moncunill-Experimentacio-nous-materials.pdf">Descarregar el PDF ↓</a></div></section><a class="publication-back" href="#/#work">← Tornar als projectes</a></article>`}
function showPublicationPage(n){publicationPage=Math.max(1,Math.min(publicationPageCount,Number(n)||1));const reader=document.querySelector('.publication-reader');if(!reader)return;const file=publicationAsset(publicationPage);const button=reader.querySelector('[data-image]');button.dataset.image=file;button.dataset.caption=`Publicació · Pàgina ${publicationPage} de ${publicationPageCount}`;button.setAttribute('aria-label',`Amplia la pàgina ${publicationPage} de la publicació`);const img=button.querySelector('img');setImageSource(img,file);img.alt=`Pàgina ${publicationPage}: ${publicationTitle}`;reader.querySelector('select').value=String(publicationPage);reader.querySelector('#publication-status').textContent=`Pàgina ${publicationPage} de ${publicationPageCount}`;reader.querySelector('[data-publication-step="-1"]').disabled=publicationPage===1;reader.querySelector('[data-publication-step="1"]').disabled=publicationPage===publicationPageCount;reader.querySelectorAll('[data-publication-page]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.publicationPage)===publicationPage)));}
document.addEventListener('click',event=>{const page=event.target.closest('[data-publication-page]');const step=event.target.closest('[data-publication-step]');if(page){showPublicationPage(page.dataset.publicationPage);document.querySelector('.publication-controls').scrollIntoView({behavior:reducedMotion?'instant':'smooth',block:'start'});}if(step)showPublicationPage(publicationPage+Number(step.dataset.publicationStep));});
document.addEventListener('change',event=>{if(event.target.id==='publication-page')showPublicationPage(event.target.value);});
